public:
    int maxVowels(string s, int k) {
        auto isV = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };
        int cur = 0;
        for (int i = 0; i < k; ++i) cur += isV(s[i]);
        int ans = cur;
        for (int i = k; i < (int)s.size(); ++i) {
            cur += isV(s[i]) - isV(s[i - k]);
            ans = max(ans, cur);
        }
        return ans;
    }
