    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        total = sum(nums)
        memo = {}

        def dfs(i: int, cur: int) -> int:
            if i == len(nums):
                return 1 if cur == target else 0
            key = (i, cur)
            if key in memo:
                return memo[key]
            memo[key] = dfs(i + 1, cur + nums[i]) + dfs(i + 1, cur - nums[i])
            return memo[key]

        if abs(target) > total:
            return 0
        return dfs(0, 0)

