class Solution {
    vector<vector<pair<int, int>>> g;
    vector<vector<int>> memo;
    int dst;
    static const int INF = 1e9;
    int dfs(int u, int left) {
        if (u == dst) return 0;
        if (left == 0) return INF;
        int& m = memo[u][left];
        if (m != -1) return m;
        int best = INF;
        for (auto [v, w] : g[u]) {
            int sub = dfs(v, left - 1);
            if (sub < INF) best = min(best, w + sub);
        }
        return m = best;
    }
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {
        this->dst = dst;
        g.assign(n, {});
        for (auto& f : flights) g[f[0]].push_back({f[1], f[2]});
        memo.assign(n, vector<int>(k + 2, -1));
        int ans = dfs(src, k + 1);
        return ans >= INF ? -1 : ans;
    }
};

