/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
    unordered_map<TreeNode*, int> memo;
    int dfs(TreeNode* node) {
        if (!node) return 0;
        if (memo.count(node)) return memo[node];
        int take = node->val;
        if (node->left) take += dfs(node->left->left) + dfs(node->left->right);
        if (node->right) take += dfs(node->right->left) + dfs(node->right->right);
        int skip = dfs(node->left) + dfs(node->right);
        return memo[node] = max(take, skip);
    }
public:
    int rob(TreeNode* root) {
        memo.clear();
        return dfs(root);
    }
};

