class Solution {
public:
    int waysToReachTarget(int target, vector<vector<int>>& types) {
        const int MOD = 1e9 + 7;
        vector<int> dp(target + 1);
        dp[0] = 1;
        for (auto& t : types) {
            int count = t[0], marks = t[1];
            vector<int> ndp = dp;
            for (int s = 0; s <= target; ++s) {
                if (!dp[s]) continue;
                for (int c = 1; c <= count; ++c) {
                    int ns = s + c * marks;
                    if (ns > target) break;
                    ndp[ns] = (ndp[ns] + dp[s]) % MOD;
                }
            }
            dp.swap(ndp);
        }
        return dp[target];
    }
};

