class Solution {
public:
    int countPartitions(vector<int>& nums, int k) {
        const int MOD = 1e9 + 7;
        long long total = 0;
        for (int x : nums) total += x;
        if (total < 2LL * k) return 0;
        vector<int> dp(k);
        dp[0] = 1;
        for (int x : nums) {
            if (x >= k) continue;
            for (int s = k - 1; s >= x; --s)
                dp[s] = (dp[s] + dp[s - x]) % MOD;
        }
        long long bad = 0;
        for (int s = 0; s < k; ++s) bad += dp[s];
        bad %= MOD;
        long long pow2 = 1;
        for (int i = 0; i < (int)nums.size(); ++i) pow2 = pow2 * 2 % MOD;
        return (int)((pow2 - 2 * bad % MOD + MOD) % MOD);
    }
};

