class Solution:
    def countPartitions(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        if sum(nums) < 2 * k:
            return 0
        dp = [0] * k
        dp[0] = 1
        for x in nums:
            if x >= k:
                continue
            for s in range(k - 1, x - 1, -1):
                dp[s] = (dp[s] + dp[s - x]) % MOD
        bad = sum(dp) % MOD
        pow2 = pow(2, len(nums), MOD)
        return (pow2 - 2 * bad) % MOD

